'use server';
/**
 * @fileOverview A simple flow to test the connection to the AI model.
 *
 * - pingAI - A function that returns a success message if the AI is reachable.
 */

import { ai } from '@/ai/genkit';
import { z } from 'zod';

export async function pingAI(): Promise<string> {
  return pingAIFlow();
}

const pingAIFlow = ai.defineFlow(
  {
    name: 'pingAIFlow',
    inputSchema: z.void(),
    outputSchema: z.string(),
  },
  async () => {
    try {
      // We use a simple prompt that is unlikely to fail.
      const result = await ai.generate({
        prompt: 'Say "pong"',
        model: 'googleai/gemini-2.5-flash',
        config: { temperature: 0 },
      });

      const text = result.text;
      if (text) {
        return `Connection successful. AI says: ${text}`;
      }
      return 'AI assistant is connected, but sent an empty response.';
    } catch (e: any) {
      console.error('AI ping failed:', e);
      return `AI assistant connection failed: ${e.message}`;
    }
  }
);
