'use server';

import { ai } from '@/ai/genkit';
import { InitialEstimateInputSchema } from '@/ai/schemas/initial-estimate';
import { z } from 'zod';

// This file is for extracting entities, not determining the next step.

const MessageSchema = z.object({
  role: z.enum(['user', 'model']),
  content: z.string(),
});

// This is the input for the overall flow
const ExtractEntitiesInputSchema = z
  .array(MessageSchema)
  .describe('The full conversation history.');

// This is the input for the prompt itself
const PromptInputSchema = z.object({
  history: ExtractEntitiesInputSchema,
});

const ExtractEntitiesOutputSchema = InitialEstimateInputSchema.partial().describe(
  "The entities extracted from the last user's message in the history."
);

export async function extractEntities(
  input: z.infer<typeof ExtractEntitiesInputSchema>
): Promise<z.infer<typeof ExtractEntitiesOutputSchema>> {
  return extractEntitiesFlow(input);
}

const extractEntitiesPrompt = ai.definePrompt({
  name: 'extractEntitiesPrompt',
  input: { schema: PromptInputSchema }, // Use the object schema here
  output: { schema: ExtractEntitiesOutputSchema },
  prompt: `You are an AI assistant that extracts data from a conversation.
Your task is to analyze the conversation history and extract values for the following fields from the user's messages:
- squareFootage: The total square footage of the project area.
- planType: The floor plan type.
- privateOffices: The number of private offices to be built.
- ceilingType: The type of ceiling.
- ceilingHeight: The height of the ceiling in feet.

Look at the last user message and the conversation context to determine what information they are providing.

You MUST respond with a valid JSON object containing only the fields you were able to extract.
If the user's last message does not contain any of this information, return an empty JSON object.

Conversation History:
{{#each history}}
{{role}}: {{content}}
{{/each}}`,
  config: {
    model: 'googleai/gemini-2.5-flash',
    temperature: 0.0,
  },
});

const extractEntitiesFlow = ai.defineFlow(
  {
    name: 'extractEntitiesFlow',
    inputSchema: ExtractEntitiesInputSchema, // Flow input remains an array
    outputSchema: ExtractEntitiesOutputSchema,
  },
  async (input) => {
    // When calling the prompt, wrap the input array in an object
    const { output } = await extractEntitiesPrompt({ history: input });
    if (!output) {
      // If the model fails to extract, return an empty object to avoid crashing.
      return {};
    }
    return output;
  }
);
